styles:
/* Диалог токена GitHub (раньше — style.cssText в коде модуля) */
.githubTokenDialog {
  max-width: 440px;
  border: 1px solid #47606d;
  border-radius: 10px;
  background: #16222c;
  color: #dcecf4;
  padding: 16px;
}
.githubTokenDialog h3 {
  margin: 0 0 8px;
  font-size: 15px;
}
.githubTokenDialog p {
  margin: 0 0 10px;
  font-size: 12px;
  line-height: 1.5;
  color: #9fb6c2;
}
.githubTokenDialog a {
  display: inline-block;
  margin-bottom: 10px;
  font-size: 12px;
  color: #74d9cf;
}
.githubTokenDialog input[type='password'] {
  width: 100%;
  box-sizing: border-box;
  padding: 7px;
  border-radius: 6px;
  border: 1px solid #47606d;
  background: #0f1a22;
  color: inherit;
}
.githubTokenDialog .check {
  display: flex;
  gap: 6px;
  align-items: center;
  margin: 10px 0;
  font-size: 12px;
}
/* «логин» для менеджера паролей браузера — на экране не виден */
.githubTokenUser {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.githubTokenButtons {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}
/* отказ сохранения: окно по тексту, на телефоне — в ширину экрана с полями 16 px */
.githubSaveError {
  box-sizing: border-box;
  width: max-content;
  max-width: min(380px, calc(100vw - 32px));
}
.githubSaveError p {
  color: #dcecf4;
  font-size: 13px;
  overflow-wrap: anywhere;
}
.githubSaveError::backdrop {
  background: #03080c99;
}
@media (pointer: coarse) {
  .githubSaveError button {
    min-height: 44px;
    min-width: 88px;
  }
}

/* «Настройки вида применены…» — для сведения; на телефоне строка статуса ложится
   поверх модели, там её не показываем (ход сохранения и ошибки — показываем) */
@media (max-width: 760px) {
  #githubSaveStatus.githubSaveInfo {
    display: none;
  }
}

