styles:
/* Сечение (UI-001, П-4). Строка в панели и плавающее окно — общий стиль оболочки
   (toolbar/style.css: .toolStack, .floatWin, ползунок, фокус; icon_controls/style.css:
   «Значки / Подписи»). Здесь — только своё. */

#sectionPositionValue:empty {
  display: none;
}

/* Без тулбара (старая оболочка): строка и настройки — в выпадающем меню блока */
#sectionPanel[hidden] {
  display: none;
}
#sectionPanel {
  border-left: 1px solid #33454f;
  padding-left: 10px;
}
#sectionTools .toolPopup {
  position: fixed;
  left: 50%;
  top: 76px;
  transform: translateX(-50%);
  width: 440px;
  max-width: calc(100vw - 32px);
  box-sizing: border-box;
  max-height: 70vh;
  overflow: auto;
}
#sectionTools .toolStack {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
#sectionTools #sectionPosition {
  display: block;
  width: 100%;
  min-width: 0;
}

