styles:
/* список сохранённых сечений */
.sectionViewsPopup {
  min-width: 300px;
  max-width: 380px;
}
.sectionViewsList {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 55vh;
  overflow: auto;
  margin-bottom: 6px;
}
/* строка: [радио][превью][обозначение][обновить][развернуть][удалить], описание —
   второй строкой под превью: кнопки не выдавливает и ширину окна не задаёт */
.sectionViewRow {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr) repeat(3, auto);
  align-items: center;
  gap: 4px 6px;
  padding: 3px 4px;
  border: 1px solid transparent;
  border-radius: 5px;
}
.sectionViewRow:not([data-id]) {
  grid-template-columns: auto 1fr;
}
.sectionViewRow.on {
  border-color: #e53935;
  background: #e5393518;
}
.sectionViewRow img {
  width: 72px;
  height: 46px;
  object-fit: cover;
  border-radius: 3px;
  background: #0b1217;
  flex: none;
}
.sectionViewRow input[type='text'] {
  width: 56px;
  flex: none;
  font-weight: 700;
  text-align: center;
}
.sectionViewRow .sectionViewMeta {
  grid-row: 2;
  grid-column: 2 / -1;
  min-width: 0;
  font-size: 11px;
  color: var(--muted-soft, #9aa9b1);
}
/* кнопки строки — значок общего набора (П-7, П-30): «Обновить», «Развернуть», «Удалить» */
.sectionViewRow > button {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  padding: 0;
}
.sectionViewRow > button > .uiIcon {
  width: 18px;
  height: 18px;
}
/* число сохранённых у значка «Сечения (N)» — только без подписей */
#sectionViewsSummary {
  position: relative;
}
.sectionViewsCount {
  display: none;
}
html.uiNoLabels .sectionViewsCount:not([hidden]) {
  display: block;
  position: absolute;
  right: 2px;
  top: -5px;
  min-width: 15px;
  height: 15px;
  padding: 0 3px;
  border-radius: 8px;
  background: #315e5d;
  color: #caffed;
  font-size: 10px;
  line-height: 15px;
  text-align: center;
}
/* телефон: цели касания не меньше 44 px */
@media (max-width: 760px), (pointer: coarse) {
  .sectionViewRow > button {
    width: 44px;
    height: 44px;
  }
  .sectionViewRow input[type='radio'] {
    width: 22px;
    height: 22px;
  }
}
.sectionViewsHint {
  display: block;
  color: var(--muted-soft, #9aa9b1);
  max-width: 340px;
}
/* обозначения на модели: номер у концов линии сечения */
.sectionMarkLabels {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 4;
}
.sectionMarkLabel {
  position: absolute;
  transform: translate(-50%, -50%);
  min-width: 18px;
  padding: 0 4px;
  border-radius: 3px;
  background: #b71c1cee;
  color: #fff;
  font: 700 13px/18px system-ui;
  text-align: center;
  pointer-events: auto;
  cursor: pointer;
}
.sectionMarkLabel.on {
  background: #e53935;
  box-shadow: 0 0 0 2px #fff8;
}
.sectionViewRow button.sectionViewUpdate[hidden] {
  display: none;
}
.sectionViewRow button.sectionViewUpdate.dirty {
  border-color: #f1c232;
  color: #f1c232;
}
/* «Сохранить текущее» и «Обозначения на модели» — столбцом и без подписей (один элемент —
   одна строка): общий .tools раскладывает в ряд */
.sectionViewsPopup .sectionViewsTools {
  display: flex;
  flex-direction: column;
  flex-wrap: nowrap;
  align-items: stretch;
  gap: 8px;
}
html.uiNoLabels .sectionViewsPopup .sectionViewsTools {
  align-items: flex-start;
}

