styles:
/* Сегмент режимов отображения: Обычный · Рентген · Каркас (токены — toolbar) */
.displayModes {
  display: flex;
  align-items: stretch;
  gap: 2px;
  padding: 2px;
  border-radius: 10px;
  background: var(--ui-fill, #2c3d47);
  flex: none;
}
.displayModes[hidden] {
  display: none;
}
#displayModes.displayModes button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: calc(var(--ui-bar, 34px) - 4px);
  padding: 0 10px;
  font-size: 13px;
  line-height: 1.2;
  white-space: nowrap;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--ui-text-secondary, #a6bac4);
}
#displayModes.displayModes button:hover {
  background: var(--hover);
  color: var(--ui-text, #e8eef0);
}
#displayModes.displayModes button[aria-pressed='true'] {
  background: var(--ui-raised, #21313e);
  border-color: var(--ui-separator, #31414b);
  color: var(--ui-text, #e8eef0);
  box-shadow: 0 1px 3px #0008;
}
.displayModes svg {
  width: 18px;
  height: 18px;
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linejoin: round;
  stroke-linecap: round;
}
#displayModes.displayModes button[aria-pressed='true'] svg {
  color: var(--ui-accent, #9ee2d0);
}
/* ноутбук с масштабом: только значки */
@media (min-width: 761px) and (max-width: 1100px) {
  .displayModes .modeLabel {
    display: none;
  }
  #displayModes.displayModes button {
    width: var(--ui-bar, 34px);
    padding: 0;
  }
}
/* телефон: значок и подпись под ним, цель 44 px */
/* телефон: каждая кнопка — полная цель 44 px; зазор вокруг выбранной рисует тень */
@media (max-width: 760px) {
  #displayModes.displayModes {
    height: 44px;
    padding: 0;
    gap: 0;
    background: var(--ui-surface, #17232df2);
    box-shadow: inset 0 0 0 1px var(--ui-separator, #31414b);
    border-radius: 12px;
  }
  #displayModes.displayModes button[aria-pressed='true'] {
    border: 0;
    border-radius: 12px;
    box-shadow:
      inset 0 0 0 3px var(--ui-surface-solid, #17232d),
      inset 0 0 0 4px var(--ui-separator, #31414b);
  }
  #displayModes.displayModes button {
    flex-direction: column;
    gap: 1px;
    width: 50px;
    height: 100%;
    padding: 0;
    font-size: 11px;
    line-height: 13px;
    letter-spacing: -0.1px;
  }
}
@media (max-width: 370px) {
  #displayModes.displayModes button {
    width: 44px;
  }
  .displayModes .modeLabel {
    display: none;
  }
}
@media (max-width: 340px) {
  #displayModes.displayModes button {
    width: 40px;
  }
}

