styles:
/* В панели «Отображение → Проекция» вид сегмента — общий стиль оболочки (.toolSegment:
   значок над подписью). Ниже — только запасное место без оболочки: угол области
   просмотра над видовым кубом (куб опущен на top 48 — viewcube/style.css), значками. */
#viewport > .projectionTools {
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 6;
  display: flex;
  gap: 2px;
  padding: 2px;
  background: #17232de8;
  border: 1px solid #415563;
  border-radius: 7px;
}
#viewport > .projectionTools button {
  min-width: 30px;
  height: 28px;
  padding: 3px;
  display: grid;
  place-items: center;
  border: 1px solid transparent;
  background: transparent;
  border-radius: 5px;
  color: var(--text);
}
#viewport > .projectionTools button > svg {
  width: 20px;
  height: 20px;
}
#viewport > .projectionTools button:has(> svg) > .uiLabel {
  display: none;
}
/* нажата — как любая нажатая кнопка просмотрщика */
#viewport > .projectionTools button[aria-pressed='true'] {
  background: #315e5d;
  border-color: var(--accent);
}

