.dimensionStyleRow {
  display: flex;
  align-items: center;
  gap: 8px;
  justify-content: space-between;
}
/* без оболочки (прежнее меню шаблона) — ползунок в строке */
#dimensionStyle #dimensionFontSize {
  width: 150px;
  margin: 0;
}

