styles:
/* «Назначение материалов» (П-10) — плавающее окно основы (.floatWin, toolbar/style.css):
   место, слой, рамка, шапка и прокрутка — оттуда. Здесь — начальная ширина и строки
   материалов. Список прокручивается вместе с окном, шапка остаётся сверху. */
#matEditor {
  width: 380px;
}
.matList[hidden] {
  display: none;
}
.matRow {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px 3px;
  border-top: 1px solid var(--divider);
}
.matList > .matRow:first-child,
.matList > .subtle + .matRow {
  border-top: 0;
}
.matHead {
  display: flex;
  align-items: center;
  gap: 9px;
}
.matThumb {
  width: 30px;
  height: 30px;
  border-radius: 6px;
  border: 1px solid var(--control-border);
  background-size: cover;
  background-position: center;
  flex: none;
}
.matName {
  font-size: 12.5px;
  line-height: 1.25;
  overflow-wrap: anywhere;
}
.matTools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding-left: 39px;
}
.matTools > * {
  flex: none;
}
/* выбор других модулей в строке (texture_fit «Тайл / На деталь») — той же высоты,
   что кнопки строки: цель щелчка не меньше 28 px */
.matTools > select {
  min-height: 30px;
}
/* кнопки строки — значок (П-30): рисунок из общего набора, цвет — от текста */
.matTools button {
  width: 32px;
  height: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid var(--control-border);
  background: #1d2b34;
  border-radius: 6px;
  cursor: pointer;
  color: var(--text);
}
.matTools button[hidden] {
  display: none;
}
.matIconBtn > .uiIcon {
  width: 18px;
  height: 18px;
  flex: none;
  pointer-events: none;
}
.matGlass {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-left: 39px;
  font-size: 12px;
  color: var(--muted);
}
.matGlass .range {
  flex: 1;
  min-width: 70px;
  margin: 0;
}
.matGlass output {
  width: 38px;
  text-align: right;
  color: var(--text);
}
.matTools input[type='color'] {
  width: 31px;
  height: 28px;
  padding: 0;
  border: 1px solid var(--control-border);
  border-radius: 6px;
  background: none;
  cursor: pointer;
}

/* вкладки «Материалы / Исключения» (П-21) — сегмент основы (.toolSegment в
   .floatWinBody, toolbar/style.css); здесь — только бейдж числа исключённых в углу */
#matTabExcluded {
  position: relative;
}
#matEditor .matCount {
  position: absolute;
  top: 3px;
  right: 6px;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  box-sizing: border-box;
  border-radius: 8px;
  background: var(--ui-accent-fill);
  color: var(--ui-on-accent);
  font-size: 10.5px;
  line-height: 16px;
  text-align: center;
}
#matEditor .matCount[hidden] {
  display: none;
}

.matPicker {
  position: fixed;
  z-index: 90;
  max-height: 52vh;
  overflow: auto;
  min-width: 210px;
  padding: 4px;
  background: var(--panel);
  border: 1px solid var(--popup-border);
  border-radius: 8px;
  box-shadow: 0 12px 35px #0008;
}
.matPicker button {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  color: var(--text);
  padding: 6px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 12px;
}
.matPicker button:hover,
.matPicker button:focus-visible {
  background: var(--hover);
}
.matPicker .pk {
  width: 22px;
  height: 22px;
  border-radius: 4px;
  border: 1px solid var(--control-border);
  background: #0003;
  background-size: cover;
  background-position: center;
  flex: none;
}
input.matFile {
  display: block;
  max-width: 100%;
  margin: 8px 0;
}
.matMono {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  padding-left: 39px;
  font-size: 11px;
}
.matMono .matMonoChip {
  display: inline-block;
  width: 20px;
  height: 20px;
  border: 1px solid #8ca1aa;
  border-radius: 4px;
}
dialog.matPicker {
  width: 360px;
  max-width: calc(100vw - 24px);
  max-height: 75vh;
  color: var(--text);
}
/* инструменты правки в выноске материала («Правка по сноскам» на ПК) */
.matCalloutTools button {
  min-width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 1px 5px;
  font-size: 12px;
  line-height: 18px;
}
.matCalloutTools .matIconBtn > .uiIcon {
  width: 14px;
  height: 14px;
}
.matCalloutTools select {
  min-height: 28px;
}
.matCalloutTools .matCalloutGlass {
  width: 70px;
}
.matCalloutTools output {
  font-size: 11px;
  color: var(--muted-soft, #9aa9b1);
}

/* телефон и сенсорный экран: цели касания не меньше 44 px (П-30) */
@media (max-width: 760px), (pointer: coarse) {
  .matTools button {
    width: 44px;
    height: 44px;
  }
  .matTools > select {
    min-height: 44px;
  }
  .matTools,
  .matGlass,
  .matMono {
    padding-left: 0;
  }
}
/* телефон: выноски — лентой чипов, править в них нечего — «Правка по сноскам» не
   нужна, остаётся «Назначение материалов» (окно — во всю ширину над листом, место
   ставит основа). !important и #layerTools — значки (icon_controls) ставят кнопкам
   display с !important (проба на S24). */
@media (max-width: 760px) {
  #matEditorOpen,
  html.iconControls #layerTools #matEditorOpen {
    display: none !important;
  }
}

