styles:
.assemblerTools {
  flex-wrap: nowrap !important;
  overflow-x: auto !important;
  overflow-y: hidden !important;
}
.assemblerToolItems {
  display: contents;
}
.assemblerTools > *,
.assemblerToolItems > * {
  flex: none;
}
.assemblerTools .opacityTool {
  margin: 0 !important;
  flex-wrap: nowrap !important;
}
.assemblerTools #assemblerSeparation {
  width: 90px;
}
.assemblerTools #assemblerDrawing,
.assemblerTools #assemblerPartDimensions {
  white-space: nowrap;
}
@media (max-width: 760px) {
  .assemblerTools #assemblerSeparation {
    width: 70px;
  }
  .assemblerTools #assemblerDrawing {
    font-size: 0;
  }
  .assemblerTools #assemblerDrawing:after {
    content: attr(data-label);
    font-size: 12px;
  }
}
/* П-14. Блок «Сборочные единицы». ПК: под меню слева, позади всех окон и меню (слой
   ниже меню --z-rail), по содержимому, не шире 240 px; left/top/max-height ставит
   модуль (adapter.js, placeUnits), много узлов — прокрутка списка внутри. Телефон:
   последняя строка листа сборщика (Д-72), прокручивается вместе с листом.
   Прежние правила .assemblyUnits* в toolbar/style.css к блоку не относятся. */
#assemblyUnits {
  position: fixed;
  z-index: calc(var(--z-rail, 20) - 1);
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: max-content;
  min-width: 0;
  max-width: 240px;
  padding: 8px;
  box-sizing: border-box;
  border: 1px solid var(--ui-separator, #31414b);
  border-radius: var(--ui-radius-m, 14px);
  background: var(--ui-surface, rgb(23 35 45 / 0.95));
  color: var(--ui-text, #e8eef0);
  font-family: var(--ui-font, system-ui);
}
#assemblyUnits[hidden] {
  display: none;
}
#assemblyUnits .assemblyUnitsHead {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  padding: 0 2px;
  font-size: 12px;
  font-weight: 600;
  line-height: 16px;
  color: var(--ui-text-secondary, #a6bac4);
  white-space: nowrap;
}
#assemblyUnits .assemblyUnitsHead > .uiIcon {
  width: 16px;
  height: 16px;
  color: var(--ui-accent, #9ee2d0);
}
#assemblyUnitsList {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
}
/* строка узла: [глаз][позиция][вписать][позиции с прозрачностью]; цвет — слоя узла */
.assemblyUnitLine {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 2px;
  border-left: 3px solid transparent;
  border-radius: 8px;
  background: var(--ui-raised, #21313e);
}
.assemblyUnitLine.assemblyUnitTinted {
  border-left-color: var(--unit-layer);
  background: color-mix(in srgb, var(--unit-layer) 18%, var(--ui-raised, #21313e));
}
.assemblyUnitLine:has(> button[data-unit][aria-pressed='true']) {
  box-shadow: inset 0 0 0 1px var(--ui-accent, #9ee2d0);
}
#assemblyUnitsList .assemblyUnitLine > button {
  min-height: var(--ui-hit, 32px);
  margin: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: inherit;
  font-size: 12px;
}
#assemblyUnitsList .assemblyUnitLine > button[data-unit] {
  flex: 1 1 auto;
  min-width: 0;
  padding: 0 8px;
  overflow: hidden;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}
#assemblyUnitsList .assemblyUnitLine > button[data-unit][aria-pressed='true'] {
  color: var(--ui-on-accent, #caffed);
  font-weight: 600;
}
#assemblyUnitsList .assemblyUnitLine > button:hover {
  background: var(--hover, #304654);
}
#assemblyUnitsList button[data-unit]:not([data-depth='0'])::before {
  content: '↳ ';
  opacity: 0.65;
}
#assemblyUnitsList .assemblyUnitAction {
  flex: none;
  display: grid;
  place-items: center;
  width: var(--ui-hit, 32px);
  padding: 0;
  color: var(--ui-text-secondary, #a6bac4);
}
#assemblyUnitsList .assemblyUnitAction > .uiIcon {
  width: 16px;
  height: 16px;
}
#assemblyUnitsList .assemblyUnitAction[data-tool='eye'][data-state='off'] {
  color: var(--ui-text-tertiary, #7f97a5);
}
#assemblyUnitsList .assemblyUnitAction[data-tool='through'][data-state='on'] {
  color: var(--ui-accent, #9ee2d0);
}
#assemblyUnitsList .assemblyUnitAction[data-tool='through'][data-state='off'] {
  color: var(--ui-text-tertiary, #7f97a5);
}
/* телефон: строка листа сборщика во всю ширину, без своего слоя и прокрутки */
#assemblyUnits.assemblyUnitsInSheet {
  position: static;
  z-index: auto;
  width: 100%;
  max-width: none;
  max-height: none;
  background: transparent;
}
#assemblyUnits.assemblyUnitsInSheet #assemblyUnitsList {
  overflow: visible;
}
#assemblerLabels .assemblerCallout {
  position: absolute;
  box-sizing: border-box;
  padding: 3px 5px;
  border-radius: 4px;
  font: 11px/14px system-ui;
  white-space: pre-line;
  overflow: hidden;
  pointer-events: auto;
  cursor: pointer;
  background: #193c55f2;
  border: 1px solid #6db6df;
  color: var(--text);
  overflow-wrap: anywhere;
}
#assemblerLabels .assemblerCallout[aria-pressed='true'] {
  background: #286589;
  border: 2px solid var(--accent);
  color: #fff;
  z-index: 1;
}
/* окно чертежа детали (drawing.js); раньше — встроенные стили в коде */
dialog.assemblerDrawing {
  width: 94vw;
  max-width: 1600px;
  height: 92vh;
  grid-template-rows: auto auto auto minmax(0, 1fr);
  background: #17232d;
  color: #e6eef3;
  border: 1px solid #71828d;
  padding: 12px;
}
dialog.assemblerDrawing[open] {
  display: grid;
}
.assemblerDrawingBody {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(260px, 1fr);
  gap: 10px;
  min-height: 0;
  overflow: hidden;
}
.assemblerDrawing .assemblerDrawingSvg {
  background: #f4f5f2;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  touch-action: none;
}
.assemblerDrawingSide {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.assemblerDrawing .assemblerHoleProperties {
  padding: 8px;
  border: 1px solid #526776;
  border-radius: 5px;
  font-size: 12px;
}
.assemblerDrawing .assemblerHoleTable {
  min-height: 0;
  overflow: auto;
  flex: 1;
}
.assemblerHoleTable table {
  width: 100%;
  font-size: 12px;
  border-collapse: collapse;
}
.assemblerHoleTable th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: #21313e;
  padding: 6px;
}
.assemblerHoleTable td {
  padding: 5px;
}
/* кромки детали: номер (цвет толщины слева), толщина, название, артикул */
.assemblerDrawing .assemblerEdgeLegend table {
  width: 100%;
  font-size: 12px;
  border-collapse: collapse;
}
.assemblerEdgeLegend caption {
  text-align: left;
  font-weight: 600;
  padding: 0 0 4px;
}
.assemblerEdgeLegend th {
  background: #21313e;
  padding: 5px;
  text-align: left;
}
.assemblerEdgeLegend td {
  padding: 4px 5px;
  vertical-align: top;
}
.assemblerEdgeLegend p {
  margin: 4px 0 0;
  font-size: 11px;
}
.assemblerHoleTable tbody tr {
  cursor: pointer;
}
/* на узком экране — чертёж над таблицей */
@media (max-width: 650px) {
  .assemblerDrawingBody {
    grid-template-columns: minmax(0, 1fr) !important;
    grid-template-rows: minmax(180px, 1fr) minmax(120px, 1fr);
  }
}
/* слой сносок поверх холста (раньше — встроенные стили в коде модуля) */
#assemblerLabels {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}
#assemblerLeaders {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}
/* телефон: номер прямо на детали — компактная пилюля без рамки-выноски */
#assemblerLabels .assemblerCallout.balloon {
  padding: 1px 5px;
  border-radius: 9px;
  border-color: #ffcc70;
  background: #17303dd9;
  text-align: center;
}
/* «Не поместилось номеров: N — приблизьте модель» — над подвалом, по центру */
.assemblerHiddenHint {
  position: absolute;
  left: 50%;
  bottom: 64px;
  transform: translateX(-50%);
  padding: 4px 10px;
  border: 1px solid #7895a0;
  border-radius: 12px;
  background: #17303de8;
  color: var(--text);
  font: 12px/16px system-ui;
  white-space: nowrap;
  pointer-events: none;
}
.assemblerHiddenHint[hidden] {
  display: none;
}

/* не нажата — только цветная обводка (фон как у всех кнопок), нажата — заливка:
   иначе не понять, включён ли режим */
#assemblerOpen,
#assemblerOpen.viewerIconControl {
  color: #c5eaff;
  border-color: #6db6df;
}
#assemblerOpen[aria-pressed='true'],
html.iconControls #assemblerOpen[aria-pressed='true'] {
  background: #286589;
  color: #fff;
  border-color: #8dd6ff;
}
/* Чертёж детали: значки у кнопок; на телефоне — только значки, без подсказки */
.assemblerDrawing .adIcon {
  display: none;
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  vertical-align: middle;
}
.assemblerDrawing .assemblerDrawingSvg {
  touch-action: none; /* щипок двумя пальцами зумирует чертёж, а не страницу */
}
@media (max-width: 700px) {
  .assemblerDrawing .adIcon {
    display: inline-block;
  }
  .assemblerDrawing .adLabel,
  .assemblerDrawing .assemblerDrawingHint {
    display: none;
  }
  .assemblerDrawing .tools button {
    min-width: 40px;
    padding: 6px 8px;
  }
}
/* Выноски сборщика: все детали — один цвет (синий), все сборочные единицы — другой
   (янтарный, жирная рамка) — единицу видно среди деталей с первого взгляда */
#assemblerLabels .assemblerCallout {
  background: #173246;
  border-color: #6db6df;
}
#assemblerLabels .assemblerCallout.assemblerUnitCallout {
  background: #7a4e12;
  border-color: #ffb74d;
  border-width: 2px;
  font-weight: 700;
  color: #fff;
}
#assemblerLabels .assemblerCallout[aria-pressed='true'] {
  border: 2px solid var(--accent);
}
/* В панели инструмента и листе — правило оболочки: один элемент — одна строка
   (toolbar, .toolStack; владелец 24.10.2026). Строка не прокручивается вбок
   (на S24 у «Разноса» была полоса прокрутки), ползунок — во всю ширину. */
.toolPanelBody .assemblerTools {
  flex-wrap: nowrap !important;
  overflow: visible !important;
}
.toolPanelBody .assemblerTools #assemblerSeparation {
  flex: 1 1 auto;
  width: auto;
}
.toolPanelBody .assemblerTools :is(#assemblerDrawing, #assemblerPartDimensions) {
  margin: 0;
}

