styles:
.hardwareCatalog {
  position: absolute;
  z-index: 4;
  left: 8px;
  right: 8px;
  bottom: 8px;
  height: 188px;
  padding: 7px;
  background: #101c24ef;
  border: 1px solid #415563;
  border-radius: 9px;
  pointer-events: auto;
}
.hardwareCatalog[hidden],
.hardwareCatalogToggle[hidden] {
  display: none;
}
.hardwareCatalogToggle {
  position: absolute;
  z-index: 5;
  left: 8px;
  bottom: 8px;
  box-shadow: 0 3px 12px #0008;
  white-space: nowrap;
}
.hardwareCatalogToggle[aria-expanded='true'] {
  bottom: 211px;
}
.hardwareCatalogHead {
  height: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: #a6bac4;
}
.hardwareCatalogRail {
  display: flex;
  gap: 7px;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 2px 1px 7px;
  scroll-snap-type: x proximity;
}
.hardwareCard {
  width: 138px;
  height: 142px;
  flex: 0 0 138px;
  display: grid;
  grid-template-rows: 30px 76px 28px;
  padding: 4px;
  text-align: left;
  background: var(--panel);
  border: 1px solid #415563;
  border-radius: 7px;
  scroll-snap-align: start;
}
.hardwareCard[aria-pressed='true'] {
  background: #315e5d;
  border-color: var(--accent);
}
.hardwareCardName {
  font-size: 11px;
  line-height: 14px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.hardwareCardImage {
  width: 100%;
  height: 76px;
  object-fit: contain;
  background: #edf0f1;
  border-radius: 4px;
}
.hardwareCardPlaceholder {
  display: grid;
  place-items: center;
  color: #617985;
  background: var(--divider);
  font-size: 24px;
}
.hardwareCardMeta {
  font-size: 10px;
  line-height: 13px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.hardwareCardMeta strong {
  display: block;
  font-size: 11px;
  color: var(--text);
}
@media (max-width: 760px) {
  .hardwareCatalog {
    height: 153px;
    padding: 5px;
  }
  .hardwareCatalogToggle[aria-expanded='true'] {
    bottom: 176px;
  }
  .hardwareCatalogHead {
    height: 20px;
  }
  .hardwareCard {
    width: 112px;
    height: 114px;
    flex-basis: 112px;
    grid-template-rows: 26px 58px 23px;
    padding: 3px;
  }
  .hardwareCardImage {
    height: 58px;
  }
  .hardwareCardName {
    font-size: 10px;
    line-height: 12px;
  }
  .hardwareCardMeta {
    font-size: 9px;
    line-height: 11px;
  }
  .hardwareCardMeta strong {
    font-size: 10px;
  }
}
/* подсказки внизу — в один ряд с кнопкой «Фурнитура», справа от неё (adapter.js
   ставит --footerLeft/--footerBottom по кнопке); без кнопки — как в шаблоне */
.footer {
  bottom: var(--footerBottom, 10px);
  left: var(--footerLeft, 306px);
}
/* не влезли в ряд — переносятся вверх: первая подсказка всегда рядом с кнопкой */
.footer {
  align-items: flex-end;
}
.footerHints {
  flex-wrap: wrap-reverse;
}

