function imageToCanvas(image,flipY,size=1024){if((typeof HTMLImageElement!=='undefined'&&image instanceof HTMLImageElement)||(typeof HTMLCanvasElement!=='undefined'&&image instanceof HTMLCanvasElement)||(typeof OffscreenCanvas!=='undefined'&&image instanceof OffscreenCanvas)||(typeof ImageBitmap!=='undefined'&&image instanceof ImageBitmap)){const scale=size/Math.max(image.width,image.height);const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*Math.min(1,scale)));canvas.height=Math.max(1,Math.round(image.height*Math.min(1,scale)));const context=canvas.getContext('2d');if(flipY===true){context.translate(0,canvas.height);context.scale(1,-1);}
context.drawImage(image,0,0,canvas.width,canvas.height);return canvas;}else{throw new Error('THREE.USDZExporter: No valid image data found. Unable to process texture.');}}
function canvasBytes(canvas,type){const url=canvas.toDataURL(type,0.85),text=atob(url.slice(url.indexOf(',')+1)),bytes=new Uint8Array(text.length);for(let i=0;i<text.length;i++)bytes[i]=text.charCodeAt(i);return bytes;}
let crcTable=null;function crc32(bytes){if(!crcTable){crcTable=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;crcTable[n]=c>>>0;}}
