function buildMatrixRow(array,offset){return`(${array[offset + 0]}, ${array[offset + 1]}, ${array[offset + 2]}, ${array[offset + 3]})`;}
function buildMeshObject(geometry,doubleSided){const mesh=buildMesh(geometry,doubleSided);return`
def "Geometry"
{
${mesh}
}
`;}
function buildMesh(geometry,doubleSided){const name='Geometry';const attributes=geometry.attributes;const count=attributes.position.count;return`
	def Mesh "${name}"
	{
		int[] faceVertexCounts = [${buildMeshVertexCount(geometry)}]
