styles:
/* В комнате (RF-029). Кнопка — общий вид кнопок раздела «Отображение» (toolbar).
   Скрытая (AR здесь не работает) — по id: общее правило кнопок листа задаёт display
   сильнее, чем [hidden]. Здесь же — занятое состояние, сообщение внизу и наложение поверх камеры в WebXR. */
.arOpen[aria-busy='true'] {
  opacity: 0.6;
  cursor: progress;
}
#arOpen[hidden],
#arReal[hidden],
#arWalls[hidden],
#arTurn[hidden],
.arStatus[hidden],
.arOverlay[hidden] {
  display: none;
}
/* Наложение во весь экран над камерой — минимум поверх обзора (замечание владельца
   04.11.2026): подсказка — узкой строкой сверху слева и гаснет; справа — столбец круглых
   кнопок без подписей. Само наложение прозрачно и ловит касания (поставить, повернуть). */
.arOverlay {
  position: fixed;
  inset: 0;
  z-index: 300;
  background: transparent;
  touch-action: none;
  user-select: none;
}
.arHint {
  position: absolute;
  top: max(10px, env(safe-area-inset-top));
  left: 12px;
  right: 68px;
  width: fit-content;
  margin: 0;
  padding: 5px 10px;
  border-radius: 10px;
  background: rgba(16, 23, 29, 0.6);
  color: #f2f5f7;
  font-size: 12px;
  line-height: 1.3;
  transition: opacity 0.4s;
}
.arHint.arGone {
  opacity: 0;
}
.arTools {
  position: absolute;
  top: max(10px, env(safe-area-inset-top));
  right: max(10px, env(safe-area-inset-right));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
}
.arTool {
  position: relative;
  display: grid;
  place-items: center;
  min-width: 44px;
  height: 44px;
  padding: 0;
  border: 0;
  border-radius: 22px;
  background: rgba(16, 23, 29, 0.6);
  color: #f2f5f7;
  font: inherit;
  font-size: 12px;
}
.arTool[aria-pressed='true'] {
  color: #9ee2d0;
}
.arTool .uiIcon {
  width: 20px;
  height: 20px;
}
/* режим «На пол / К стене» (RF-042): значок — текущий режим; «К стене» — бирюзовый, как прицел на стене */
#arPlace[aria-pressed='true'] .arIconFloor,
#arPlace:not([aria-pressed='true']) .arIconWall {
  display: none;
}
.arTool:focus-visible {
  outline: 2px solid #9ee2d0;
  outline-offset: 2px;
}
/* число отмеченных стен — меткой в углу кнопки */
.arBadge {
  position: absolute;
  top: -2px;
  right: -2px;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 8px;
  background: #9ee2d0;
  color: #10171d;
  font-size: 10px;
  font-weight: 600;
  line-height: 16px;
  text-align: center;
}
/* Окно «Что показать в комнате» (общее плавающее окно): строка счёта, дерево с флажками
   (прокрутка внутри), «Отметить всё» и «Показать в комнате» — столбцом. Строка дерева —
   [раскрыть][флажок][название][число деталей]; отступ — по уровню. */
.arPickCount {
  margin: 0;
  color: var(--ui-text-secondary, inherit);
  font-size: 12px;
}
.arTree {
  width: min(280px, calc(100vw - 48px));
  max-height: min(50vh, 420px);
  overflow: auto;
  border: 1px solid var(--ui-separator);
  border-radius: var(--ui-radius-s);
  padding: 4px 0;
}
.arKids[hidden] {
  display: none;
}
.arRow {
  display: flex;
  align-items: center;
  gap: 2px;
  min-height: var(--ui-hit);
  padding: 0 6px 0 calc(var(--ar-level, 0) * 14px + 4px);
}
/* у детали без вложенных — место кнопки раскрытия, чтобы флажки стояли столбцом */
.arNode > .arRow:only-child {
  padding-left: calc(var(--ar-level, 0) * 14px + 4px + var(--ui-hit) * 0.75);
}
.arCaret {
  flex: none;
  display: grid;
  place-items: center;
  width: calc(var(--ui-hit) * 0.75);
  height: var(--ui-hit);
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
}
.arCaret > .uiIcon {
  width: 16px;
  height: 16px;
  transition: transform 0.15s;
}
.arCaret[aria-expanded='true'] > .uiIcon {
  transform: rotate(90deg);
}
.arCheck {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: var(--ui-hit);
  cursor: pointer;
}
.arCheck > input {
  flex: none;
  margin: 0;
  width: 16px;
  height: 16px;
  accent-color: var(--ui-accent);
}
.arName {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.arCheck > small {
  flex: none;
  color: var(--ui-text-tertiary, inherit);
  font-size: 11px;
}
.arCaret:focus-visible,
.arRow label:has(> input:focus-visible) {
  outline: 2px solid #9ee2d0;
  outline-offset: 2px;
}
/* капсула «На пол / К стене» — общий вид .toolSegment (toolbar/style.css); пояснение под ней
   переносится по ширине окна и ширину не задаёт; у «Скачать 3D» (GLB) их нет */
.arPlace[hidden],
.arPlaceNote[hidden] {
  display: none;
}
.floatWinBody.toolStack > .arPlaceNote {
  width: 0;
  min-width: 100%;
}
.floatWinBody.toolStack > .arPickGo {
  background: var(--ui-accent-fill);
  border-color: var(--ui-accent);
  justify-content: center;
}
.floatWinBody.toolStack > .arPickGo:disabled {
  opacity: 0.5;
}
/* Масштаб — круглая кнопка с числом «75 %» (шире, если число длинное) */
.arScale {
  padding: 0 8px;
}
.arScaleValue {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

