styles:
/* «Обновить просмотрщик» — в верхней строке перед языком и дискетой, в их размер;
   акцентная, чтобы новую версию заметили */
#toolbar > .viewerUpdateButton {
  flex: none;
  align-self: center;
  display: flex;
  align-items: center;
  gap: 5px;
  min-height: 32px;
  margin: 3px;
  padding: 4px 9px;
  border: 1px solid #2f8f84;
  border-radius: 7px;
  background: #1d4a47;
  color: #bff3ec;
  font-size: 12px;
  font-weight: 600;
}
#toolbar > .viewerUpdateButton:hover:not(:disabled) {
  background: #25605b;
}
#toolbar > .viewerUpdateButton[hidden] {
  display: none;
}
#toolbar > .viewerUpdateButton:disabled {
  opacity: 0.75;
  cursor: progress;
}
/* на телефоне — только значок: строка и так тесная */
@media (max-width: 760px) {
  #toolbar > .viewerUpdateButton {
    margin: 3px 0;
    padding: 4px 6px;
  }
  #viewerUpdateLabel {
    display: none;
  }
}

