styles:
/* Значение справа от ползунка — его можно нажать и ввести число вручную */
input[type='range'] + output,
input[type='range'] + span {
  cursor: text;
  border-bottom: 1px dotted transparent;
}
input[type='range'] + output:hover,
input[type='range'] + span:hover,
input[type='range'] + output:focus-visible,
input[type='range'] + span:focus-visible {
  border-bottom-color: var(--muted-soft);
}
.rangeEntry {
  box-sizing: border-box;
  height: 24px;
  padding: 1px 5px;
  border: 1px solid var(--accent);
  border-radius: 5px;
  background: #0f1a21;
  color: var(--text);
  font: inherit;
  font-size: 12px;
  text-align: right;
  flex: none;
}

