styles:
/* ── Строение кнопки (П-26; ui-rules, п. 2 и 4) ──
   У кнопки два свойства: значок и подпись; подпись — «убираемая», кроме главных
   кнопок левого меню (.toolRail), названий разделов и кнопок с [data-label-fixed].
   Значок — <svg class="uiIcon"> (или <span class="uiIcon">) внутри кнопки, либо маска
   ::before у .viewerIconControl (--viewer-control-icon; так значок переживает смену
   текста кнопки кодом). Подпись — <span class="uiLabel"> или собственный текст кнопки.
   Значок — у левого края, подпись — сразу от значка; без подписи значок остаётся слева.
   Варианты одной настройки (.toolSegment, .views) — значок над подписью, по центру.
   Настройки (adapter.js): html.iconControls — «Значки» включены, html.uiNoLabels —
   «Подписи» выключены. Кнопка без значка подпись не теряет; без подписи — не теряет
   значок: ни в одном сочетании кнопка не пустеет. Меню слева и верхняя строка держат
   свою раскладку (toolbar/style.css): значок там есть всегда. Текст подписи остаётся
   в DOM: перевод, подсказка title и имя для экранного диктора. ── */
/* размер и маска значка .uiIcon — общий стиль оболочки (toolbar/style.css) */
/* строка-флажок со значком: [квадрат][значок][подпись][число] — значок стоит первым
   ребёнком строки (adapter.js), место за квадратом даёт порядок */
label:has(> .uiIcon) > input:is([type='checkbox'], [type='radio']) {
  order: -2;
}
label:has(> .uiIcon) > .uiIcon {
  order: -1;
}

/* значок-маска у прежних кнопок: при «Значках»; в меню слева и у кнопок выбора в
   верхней строке — всегда (RF-013) */
html.iconControls .viewerIconControl::before,
.toolRail > .viewerIconControl::before,
#toolbar #selectionTools .viewerIconControl::before {
  content: '';
  display: block;
  flex: none;
  width: 18px;
  height: 18px;
  background: currentColor;
  mask: var(--viewer-control-icon) center / contain no-repeat;
  -webkit-mask: var(--viewer-control-icon) center / contain no-repeat;
}
.toolRail > .viewerIconControl::before {
  width: 22px;
  height: 22px;
}
html.iconControls .viewerColorIcon::before,
.toolRail > .viewerColorIcon::before,
#toolbar #selectionTools .viewerColorIcon::before {
  mask: none;
  -webkit-mask: none;
  background: var(--viewer-control-icon) center / contain no-repeat;
}
#visibilityMode.viewerIconControl[aria-pressed='false'] {
  --viewer-control-icon: var(--viewer-assembly-icon) !important;
}
/* кнопки со значком вне панелей и списков (верхняя строка справа): значок + подпись */
#toolbar > .viewerIconControl {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
/* на ПК значок у кнопок выбора заменяет короткую подпись-символ (↶, ⚙) */
@media (min-width: 761px) {
  #toolbar #selectionTools .viewerIconControl::after {
    content: none !important;
  }
}

/* ── «Значки» выключены: значки у кнопок с подписью скрыты (меню слева и верхняя
   строка — свои; глаз видимости — это состояние, а не украшение: виден всегда) ── */
html:not(.iconControls)
  :is(button, summary, label, div):has(> .uiLabel):not(#toolbar *, .toolRail *)
  > .uiIcon:not(.uiEyeIcon) {
  display: none;
}

/* ── «Подписи» выключены: убираемые подписи скрыты, кнопки сжимаются до значка ── */
html.uiNoLabels :is(button, summary, label, div):has(> .uiIcon):not([data-label-fixed]) > .uiLabel {
  display: none;
}
html.uiNoLabels .viewerIconControl:not(.toolRail > *):not([data-label-fixed]) {
  font-size: 0 !important;
  line-height: 0 !important;
  gap: 0 !important;
}
/* верхняя строка на ПК: кнопки — квадрат по значку (на телефоне ширины — у оболочки) */
@media (min-width: 761px) {
  html.uiNoLabels #toolbar #displayModes button {
    width: var(--ui-bar, 34px);
    padding: 0;
    justify-content: center;
  }
  html.uiNoLabels #toolbar #selectionTools .viewerIconControl,
  html.uiNoLabels #toolbar > .viewerIconControl {
    width: var(--ui-bar, 34px);
    min-width: var(--ui-bar, 34px);
    padding: 0;
    justify-content: center;
  }
}
html.uiNoLabels #toolbar #selectionTools button::after {
  content: none !important;
}
/* строки панели, плавающих окон и «☰»: кнопка — по размеру значка, у левого края */
html.uiNoLabels
  :is(.toolPanelBody, .floatWin, #viewerMenuPopup)
  :is(.viewerIconControl, :has(> .uiIcon)):not([data-label-fixed]):not(:is(.toolSegment, .views) > *):not(
    :has(> input[type='range'])
  ) {
  width: auto !important;
  min-width: var(--ui-hit, 44px);
  max-width: none;
  align-self: flex-start;
  flex: none;
  justify-content: flex-start;
}
html.uiNoLabels
  :is(.toolPanelBody, .floatWin)
  :is(.featureRow, .toolStack)
  > :is(span:has(> .viewerIconControl), .toolMenu:has(> .viewerIconControl)) {
  width: auto;
  align-self: flex-start;
}
html.uiNoLabels :is(.toolPanelBody, .floatWin) .toolMenu > .viewerIconControl {
  position: relative;
  padding-right: 26px !important;
}
/* ползунок без подписи: значок, значение — строкой, ползунок под ними */
html.uiNoLabels
  :is(.toolPanelBody, .floatWin, .toolPopupPortal)
  :is(label, .opacityTool):has(> input[type='range']):has(> .uiIcon) {
  grid-template-columns: auto 1fr auto;
}

/* ── Варианты одной настройки (.toolSegment, .views) — компактно (Д-78, как режимы
   отображения вверху): два варианта — значок рядом с подписью; три и больше на узкой
   панели рядом не помещаются — значок 16 px над подписью 11 px. Капсула и выбранный —
   toolbar/style.css. ── */
:is(.toolPanelBody, .floatWin) :is(.toolSegment, .views) > :is(.viewerIconControl, :has(> .uiIcon)) {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-height: 28px;
  padding: 0 6px;
  font-size: 12px;
  line-height: 14px;
  text-align: center;
  white-space: normal;
}
:is(.toolPanelBody, .floatWin)
  :is(.toolSegment, .views):has(> :nth-child(3))
  > :is(.viewerIconControl, :has(> .uiIcon)) {
  flex: 1 0 auto;
  flex-direction: column;
  gap: 2px;
  padding: 3px 4px;
  font-size: 11px;
  line-height: 13px;
  white-space: nowrap;
}
:is(.toolPanelBody, .floatWin) :is(.toolSegment, .views) > * > .uiIcon {
  width: 16px;
  height: 16px;
  flex: none;
}
html.uiNoLabels
  :is(.toolPanelBody, .floatWin)
  :is(.toolSegment, .views)
  > :is(.viewerIconControl, :has(> .uiIcon)) {
  flex: 0 0 auto;
  width: 34px;
  min-height: 28px;
  padding: 2px;
}
@media (pointer: coarse), (max-width: 760px) {
  :is(.toolPanelBody, .floatWin) :is(.toolSegment, .views) > :is(.viewerIconControl, :has(> .uiIcon)) {
    min-height: 44px;
  }
  html.uiNoLabels
    :is(.toolPanelBody, .floatWin)
    :is(.toolSegment, .views)
    > :is(.viewerIconControl, :has(> .uiIcon)) {
    width: 44px;
    min-height: 44px;
  }
}
html.uiNoLabels :is(.toolPanelBody, .floatWin) :is(.toolSegment, .views) {
  width: auto;
  align-self: flex-start;
}

/* у меню-строки («В сносках…», «Настройки») стрелка справа рисуется оболочкой */
html.iconControls .toolPanelBody .toolMenu > .viewerIconControl::after {
  display: block;
  content: '›';
  margin-left: auto;
  font-size: 18px;
  color: var(--ui-text-tertiary, #7f97a5);
}
html.uiNoLabels .toolPanelBody .toolMenu > .viewerIconControl::after {
  position: absolute;
  right: 10px;
}

